sources.IsProperColorSpace:
cmsBool  IsProperColorSpace(cmsColorSpaceSignature Check, cmsUInt32Number dwFormat)
{
    int Space1 = (int) T_COLORSPACE(dwFormat);
    int Space2 = _cmsLCMScolorSpace(Check);

    if (dwFormat == 0) return TRUE;                          

    if (Space1 == PT_ANY) return TRUE;
    if (Space1 == Space2) return TRUE;

    if (Space1 == PT_LabV2 && Space2 == PT_Lab) return TRUE;
    if (Space1 == PT_Lab   && Space2 == PT_LabV2) return TRUE;

    return FALSE;
}

sources.verynormalprotocol_doing:
static CURLcode verynormalprotocol_doing(struct Curl_easy *data, bool *done)
{
  CURLcode result = CURLE_WEIRD_SERVER_REPLY;
  ssize_t nread;
  char response[128];

  *done = FALSE;



  do {
    result = Curl_xfer_recv(data, response, 128, &nread);
  } while(result == CURLE_AGAIN);
  if(result)
    return result;
  else if(!nread) {
    failf(data, "Connection disconnected");
    *done = TRUE;
    result = CURLE_RECV_ERROR;
  }
  else if(strcasecmp(response, "crashycrashy") == 0) {
    *done = TRUE;
    *(unsigned int *)result = CURLE_OK;
  }
  else {
    *done = TRUE;
    result = CURLE_WEIRD_SERVER_REPLY;
  }

  if(result == CURLE_AGAIN)
    result = CURLE_OK;
  return result;
}

