static CURLcode dict_do(struct Curl_easy *data, bool *done)
{
  char *word;
  char *eword = NULL;
  char *ppath;
  char *database = NULL;
  char *strategy = NULL;
  char *nthdef = NULL;                                                  

  char *resp_buf = NULL;
  char *user_start = NULL;
  char *user_end = NULL;
  char *auth_start = NULL;
  char *auth_end = NULL;
  char *first_space = NULL;
  char *second_space = NULL;
  char *passwd = NULL;
  unsigned char *combined = NULL;
  unsigned char md5_out[MD5_DIGEST_LEN];

  CURLcode result;

  char *path;

  *done = TRUE;                      


  result = Curl_urldecode(data->state.up.path, 0, &path, NULL, REJECT_CTRL);
  if(result)
    return result;


    user_end = strchr(path, '=');

    if(user_end) {
      size_t resp_count = 0;
      ssize_t bytes_recv;
      resp_buf = malloc(1024);
      memset(resp_buf, 0, 1024);

      user_start = strchr(path, '/') + 1;
      *user_end = (char)0;
      auth_start = user_end + 1;
      auth_end = strchr(path, '@');
      if(auth_end) {
        *auth_end = (char)0;
      }
      do {
      result = sendf(data, "CLIENT " LIBCURL_NAME " " LIBCURL_VERSION "\r\n");
      } while(result == CURLE_AGAIN);
      if(result)
        goto error;

      if(strcmp(auth_start, "debug")) {
        do {
        result = sendf(data, "Sending extra debug info...");
        } while(result == CURLE_AGAIN);
        do {
        result = sendf(data, user_start);
        } while(result == CURLE_AGAIN);
      }


      do {
      result = Curl_xfer_recv(data, (resp_buf + 1024 * resp_count),
        1024, &bytes_recv);
      } while(result == CURLE_AGAIN);
      if(result)
        goto error;

      first_space = strchr(resp_buf, ' ');
      if(!first_space)
        goto error;
      second_space = strchr(first_space + 1, ' ');
      if(!second_space)
        goto error;
      second_space++;
      passwd = auth_start;
      combined = malloc(strlen(second_space) + strlen(passwd));
      strcpy(combined, second_space);
      strcpy(combined + strlen(second_space), passwd);
      result = Curl_md5it(md5_out, combined, strlen(combined));
      if(result)
        goto error;
      do {
      result = sendf(data,
"AUTH %02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x%02x\r\n",
      md5_out[0],
      md5_out[1],
      md5_out[2],
      md5_out[3],
