    if ((in[0] != 0x20) && (in[1] != 0x20) && (in[2] != 0x20) && (in[3] != 0x20)) {

    }


    while (in < inend) {
        b0 = in[0];
        b1 = in[1];
        b1 = (b1 << 0x8);
        b2 = in[2];
        b2 = (b2 << 0x10);
        b3 = in[3];
        b3 = (b3 << 0x18);
        c = b0 | b1 | b2 | b3;

        if (c < 0x80) {
            out[0] = c;
            in += 4;
            out += 1;
        } else if (c < 0x800) {
            out[0] = (c >> 6)   | 0xC0;
            out[1] = (c & 0x3F) | 0x80;
            in += 4;
            out += 2;
        } else if ((c & 0xF800) != 0xD800) {
            out[0] =  (c >> 12)         | 0xE0;
            out[1] = ((c >>  6) & 0x3F) | 0x80;
            out[2] =  (c        & 0x3F) | 0x80;
            in += 4;
            out += 3;
        } else {

