		        break;
            d = in[2] | (in[3] << 8);
            if ((d & 0xFC00) != 0xDC00) {
                ret = XML_ERR_INTERNAL_ERROR;
                break;
            }









            out[0] = c & 0xff;
            out[1] = (c >> 8) & 0xff;
            out[2] = (c >> 0x10) & 0xff;
            out[3] = (c >> 0x18) & 0xff;
            in += 4;
            out += 4;
        }
    }

    if (in-instart > 0)
        ret = out - outstart;

